parameters.item/cr174_arrivaltime_local:
@if(
  or(
    empty(items('Apply_to_each_Appts')?['th_arrivaltime']),
    empty(string(first(outputs('List_rows_UTC_Offset_1')?['body/value'])?['cr174_utc_offset_standard'])),
    empty(string(first(outputs('List_rows_UTC_Offset_1')?['body/value'])?['cr174_utc_offset_daylightsaving']))
  ),
  null,
  addHours(
    items('Apply_to_each_Appts')?['th_arrivaltime'],
    int(
      if(
        first(outputs('List_rows_UTC_Offset_1')?['body/value'])?['cr174_dst'],
        first(outputs('List_rows_UTC_Offset_1')?['body/value'])?['cr174_utc_offset_daylightsaving'],
        first(outputs('List_rows_UTC_Offset_1')?['body/value'])?['cr174_utc_offset_standard']
      )
    ),
    'yyyy-MM-dd hh:mm tt'
  )
)

